using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;

namespace NaSeqMen.Editor;

internal static class HelpText
{
    public static T Attach<T>(T element, string explanation) where T : FrameworkElement
    {
        element.ToolTip = explanation;
        ToolTipService.SetInitialShowDelay(element, 350);
        ToolTipService.SetBetweenShowDelay(element, 100);
        ToolTipService.SetShowDuration(element, 120000);
        ToolTipService.SetShowOnDisabled(element, true);
        return element;
    }

