    public const string DryRun = "Включено: обработчики работают, но выходные действия через API NaSeqMen не отправляются; видно только, что было бы отправлено. Выключено: действия могут реально нажимать клавиши или управлять OBS. Режим не подавляет исходную мышь и не перехватывает прямые внешние вызовы пользовательского C#.";
    public const string Trace = "Подробный диагностический поток: исходный ввод и каждый шаг обработки. Один щелчок даёт нажатие и отпускание, а каждое из них — несколько шагов. Это не список уникальных кнопок. Двойной щелчок по строке открывает детали; старые события после переподключения не загружаются.";
    public const string Graph = "Поток слева направо: источник → условие → обработка → действие. Тяните провод от правого контакта одного блока к левому контакту другого. Двойной щелчок по блоку открывает параметры; Esc отменяет протягивание провода.";
    public static string Node(NodeView node) => node.Title + "\n" + (node.Kind switch
    {
        "source" => "Источник: выбирает, какие входящие сообщения запускают эту цепочку.",
        "condition" => "Условие: передаёт сообщение дальше только при выполнении проверки. Отказ останавливает эту ветку.",
